package com.nikahbridge;
import android.app.*;import android.os.*;import android.text.InputType;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.widget.*;import com.google.firebase.auth.*;import com.google.firebase.firestore.*;import com.google.firebase.functions.FirebaseFunctions;import com.google.firebase.ai.*;import com.google.firebase.ai.type.*;import java.util.*;import java.util.concurrent.*;
public class MainActivity extends Activity{
 FirebaseAuth auth;FirebaseFirestore db;FirebaseFunctions fn;LinearLayout root;ExecutorService ai;int green=Color.rgb(18,103,82),dark=Color.rgb(30,45,41),gray=Color.rgb(90,105,100);
 public void onCreate(Bundle b){super.onCreate(b);auth=FirebaseAuth.getInstance();db=FirebaseFirestore.getInstance();fn=FirebaseFunctions.getInstance();ai=Executors.newSingleThreadExecutor();route();} protected void onDestroy(){ai.shutdownNow();super.onDestroy();}
 void base(){ScrollView s=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(20,20,20,30);root.setBackgroundColor(Color.rgb(247,250,249));s.addView(root);setContentView(s);} TextView tx(String x,int z,boolean b){TextView t=new TextView(this);t.setText(x);t.setTextSize(z);t.setTextColor(b?dark:gray);t.setPadding(6,8,6,10);if(b)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;} void title(String x){TextView t=tx(x,27,true);t.setGravity(17);root.addView(t);} Button bt(String x,boolean fill){Button b=new Button(this);b.setText(x);b.setAllCaps(false);b.setTextSize(16);b.setTextColor(fill?Color.WHITE:green);GradientDrawable g=new GradientDrawable();g.setColor(fill?green:Color.WHITE);g.setCornerRadius(18);if(!fill)g.setStroke(2,green);b.setBackground(g);root.addView(b,new LinearLayout.LayoutParams(-1,62));return b;} EditText in(String h){EditText e=new EditText(this);e.setHint(h);e.setTextSize(16);root.addView(e,new LinearLayout.LayoutParams(-1,62));return e;} String v(DocumentSnapshot d,String k){Object x=d.get(k);return x==null?"":String.valueOf(x);} void toast(String x){Toast.makeText(this,x,Toast.LENGTH_LONG).show();}
 void route(){FirebaseUser u=auth.getCurrentUser();if(u==null){login();return;}u.reload().addOnSuccessListener(x->{if(!u.isEmailVerified()){verifyEmail();return;}db.collection("users").document(u.getUid()).get().addOnSuccessListener(d->{if(!d.exists()||!Boolean.TRUE.equals(d.getBoolean("profileActive")))profile();else home();});});}
 void login(){base();title("Best Nikah Bridge");root.addView(tx("Real Firebase account • Serious Nikah only • Not dating",16,false));EditText e=in("Email");e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);EditText p=in("Password (8+ characters)");p.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);Button s=bt("Sign in",true),c=bt("Create account",false);s.setOnClickListener(x->auth.signInWithEmailAndPassword(e.getText().toString().trim(),p.getText().toString()).addOnSuccessListener(y->route()).addOnFailureListener(y->toast("Sign in failed.")));c.setOnClickListener(x->auth.createUserWithEmailAndPassword(e.getText().toString().trim(),p.getText().toString()).addOnSuccessListener(y->{FirebaseUser u=y.getUser();u.sendEmailVerification();Map<String,Object> m=new HashMap<>();m.put("uid",u.getUid());m.put("profileActive",false);m.put("discoverable",false);m.put("verificationStatus","unverified");m.put("termsAccepted",false);m.put("intentConfirmed",false);db.collection("users").document(u.getUid()).set(m).addOnSuccessListener(z->verifyEmail());}).addOnFailureListener(y->toast("Account creation failed.")));}
 void verifyEmail(){base();title("Verify your email");root.addView(tx("Email verification is required before your profile becomes active.",16,false));Button r=bt("Resend verification",true),c=bt("I verified",false),o=bt("Sign out",false);r.setOnClickListener(x->{FirebaseUser u=auth.getCurrentUser();if(u!=null)u.sendEmailVerification();});c.setOnClickListener(x->{FirebaseUser u=auth.getCurrentUser();if(u!=null)u.reload().addOnSuccessListener(y->route());});o.setOnClickListener(x->{auth.signOut();login();});}
 void home(){base();title("Best Nikah Bridge");root.addView(tx("Real production baseline • mutual consent • family • safety",16,false));Button m=bt("Compatibility Matches",true),i=bt("Mutual Interests & Safe Chat",true),f=bt("Family Bridge / Wali",true),n=bt("Nikah Promise Path",true),l=bt("Living Compatibility",true),h=bt("Connection Health Check",true),q=bt("Real Verification",false),p=bt("Privacy Control Center",false),a=bt("AI Nikah Assistant",false),s=bt("Scam Shield",false),o=bt("Sign out",false);m.setOnClickListener(x->matches());i.setOnClickListener(x->connections());f.setOnClickListener(x->family());n.setOnClickListener(x->promise());l.setOnClickListener(x->living());h.setOnClickListener(x->health());q.setOnClickListener(x->verification());p.setOnClickListener(x->privacy());a.setOnClickListener(x->aiScreen());s.setOnClickListener(x->safety());o.setOnClickListener(x->{auth.signOut();login();});}
 void profile(){base();title("My Real Nikah Profile");EditText name=in("Full name"),age=in("Age 18+"),country=in("Country"),city=in("City"),gender=in("Gender"),looking=in("Looking for"),intent=in("Marriage intention"),timeline=in("Marriage timeline"),family=in("Family/Wali involvement"),deal=in("Deal-breakers"),about=in("About 30+ characters");CheckBox t=new CheckBox(this);t.setText("I accept rules and confirm genuine marriage intention.");root.addView(t);Button save=bt("Save & Activate",true),back=bt("Back",false);db.collection("users").document(auth.getUid()).get().addOnSuccessListener(d->{name.setText(v(d,"name"));age.setText(v(d,"age"));country.setText(v(d,"country"));city.setText(v(d,"city"));gender.setText(v(d,"gender"));looking.setText(v(d,"lookingFor"));intent.setText(v(d,"marriageIntent"));timeline.setText(v(d,"marriageTimeline"));family.setText(v(d,"familyInvolvement"));deal.setText(v(d,"dealbreakers"));about.setText(v(d,"about"));t.setChecked(Boolean.TRUE.equals(d.getBoolean("termsAccepted")));});save.setOnClickListener(x->{int aa;try{aa=Integer.parseInt(age.getText().toString());}catch(Exception z){toast("Age must be a number.");return;}if(aa<18||name.length()<2||country.length()<2||city.length()<2||gender.length()<2||looking.length()<2||intent.length()<2||timeline.length()<2||family.length()<2||deal.length()<5||about.length()<30||!t.isChecked()){toast("Complete all required fields.");return;}Map<String,Object> m=new HashMap<>();m.put("uid",auth.getUid());m.put("name",name.getText().toString().trim());m.put("age",aa);m.put("country",country.getText().toString().trim());m.put("city",city.getText().toString().trim());m.put("gender",gender.getText().toString().trim());m.put("lookingFor",looking.getText().toString().trim());m.put("marriageIntent",intent.getText().toString().trim());m.put("marriageTimeline",timeline.getText().toString().trim());m.put("familyInvolvement",family.getText().toString().trim());m.put("dealbreakers",deal.getText().toString().trim());m.put("about",about.getText().toString().trim());m.put("termsAccepted",true);m.put("intentConfirmed",true);m.put("profileActive",true);m.put("discoverable",true);db.collection("users").document(auth.getUid()).set(m,SetOptions.merge()).addOnSuccessListener(y->home()).addOnFailureListener(y->toast("Profile save failed."));});back.setOnClickListener(x->home());}
 void matches(){base();title("Real Compatibility Matches");db.collection("users").whereEqualTo("profileActive",true).whereEqualTo("discoverable",true).limit(100).get().addOnSuccessListener(q->{for(DocumentSnapshot d:q)if(!d.getId().equals(auth.getUid())){root.addView(tx(v(d,"name")+" • "+v(d,"age")+" • "+v(d,"country"),19,true));root.addView(tx("Why matched: intent • timeline • family • location • values",14,false));Button b=bt("Express Interest",true),r=bt("Report / Block",false);b.setOnClickListener(x->interest(d.getId()));r.setOnClickListener(x->reportBlock(d.getId()));}});Button b=bt("Back",false);b.setOnClickListener(x->home());}
 void interest(String uid){Map<String,Object> m=new HashMap<>();m.put("targetUid",uid);fn.getHttpsCallable("sendInterest").call(m).addOnSuccessListener(x->toast("Interest sent securely.")).addOnFailureListener(x->toast("Interest rejected by production safety rules."));}
 void connections(){base();title("Mutual Interests & Safe Chat");db.collection("connections").whereArrayContains("members",auth.getUid()).get().addOnSuccessListener(q->{if(q.isEmpty())root.addView(tx("No mutual connection yet.",16,false));for(DocumentSnapshot d:q){String other="";Object a=d.get("members");if(a instanceof List)for(Object z:(List<?>)a)if(!auth.getUid().equals(String.valueOf(z)))other=String.valueOf(z);if(!other.isEmpty()){String o=other;Button b=bt("Open Safe Chat • "+o,true);b.setOnClickListener(x->chat(d.getId(),o));}}});Button b=bt("Back",false);b.setOnClickListener(x->home());}
 void chat(String cid,String other){base();title("Safe Private Chat");root.addView(tx("Mutual-only. Two-message gate until the other person replies; message credits can extend it.",14,false));LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);root.addView(list);EditText e=in("Respectful message");Button send=bt("Send",true),back=bt("Back",false);Runnable load=()->db.collection("connections").document(cid).collection("messages").orderBy("createdAt",Query.Direction.ASCENDING).limitToLast(100).get().addOnSuccessListener(q->{list.removeAllViews();for(DocumentSnapshot d:q)list.addView(tx((auth.getUid().equals(v(d,"senderUid"))?"You: ":"Them: ")+v(d,"text"),15,false));});send.setOnClickListener(x->{Map<String,Object> m=new HashMap<>();m.put("connectionId",cid);m.put("receiverUid",other);m.put("text",e.getText().toString().trim());fn.getHttpsCallable("sendPrivateMessage").call(m).addOnSuccessListener(y->{e.setText("");load.run();}).addOnFailureListener(y->toast("Message blocked by mutual/two-message rule."));});back.setOnClickListener(x->home());load.run();}
 void family(){base();title("Family Bridge / Wali");root.addView(tx("Optional, authenticated and consent-based. Family access is never automatic.",15,false));EditText cid=in("Mutual connection ID"),uid=in("Family/Wali Firebase UID");Button c=bt("Create Family Bridge",true),q=bt("Send Family Question",false),back=bt("Back",false);c.setOnClickListener(x->{Map<String,Object> m=new HashMap<>();m.put("connectionId",cid.getText().toString());m.put("familyUid",uid.getText().toString());fn.getHttpsCallable("createFamilyBridge").call(m).addOnSuccessListener(y->toast("Family Bridge created securely.")).addOnFailureListener(y->toast("Active mutual connection required."));});q.setOnClickListener(x->{EditText e=new EditText(this);e.setHint("Question");new AlertDialog.Builder(this).setTitle("Question Bridge").setView(e).setPositiveButton("Send",(d,w)->{Map<String,Object> m=new HashMap<>();m.put("bridgeId",cid.getText().toString());m.put("text",e.getText().toString());fn.getHttpsCallable("sendFamilyQuestion").call(m).addOnSuccessListener(z->toast("Question sent securely."));}).setNegativeButton("Cancel",null).show();});back.setOnClickListener(x->home());}
 void promise(){base();title("Nikah Promise Path");EditText cid=in("Mutual connection ID"),stage=in("Stage"),date=in("Target date optional"),notes=in("Notes");Button s=bt("Save Real Roadmap",true),b=bt("Back",false);s.setOnClickListener(x->{Map<String,Object> m=new HashMap<>();m.put("connectionId",cid.getText().toString());m.put("stage",stage.getText().toString());m.put("targetDate",date.getText().toString());m.put("notes",notes.getText().toString());fn.getHttpsCallable("setNikahPromise").call(m).addOnSuccessListener(y->toast("Nikah Promise Path saved to Firebase.")).addOnFailureListener(y->toast("Only active mutual connections can use this."));});b.setOnClickListener(x->home());}
 void living(){base();title("Living Compatibility");EditText country=in("Country"),city=in("City"),timeline=in("Marriage timeline"),family=in("Family involvement"),children=in("Children expectations"),career=in("Career plan"),plan=in("Living plan");Button s=bt("Save Real Changes",true),share=bt("Share One Change",false),b=bt("Back",false);s.setOnClickListener(x->{Map<String,Object> m=new HashMap<>();m.put("country",country.getText().toString());m.put("city",city.getText().toString());m.put("marriageTimeline",timeline.getText().toString());m.put("familyInvolvement",family.getText().toString());m.put("childrenExpectation",children.getText().toString());m.put("careerPlan",career.getText().toString());m.put("livingPlan",plan.getText().toString());fn.getHttpsCallable("updateLivingCompatibility").call(m).addOnSuccessListener(y->toast("Living Compatibility saved securely."));});share.setOnClickListener(x->toast("Use a mutual connection to share only a selected change."));b.setOnClickListener(x->home());}
 void health(){base();title("Connection Health Check");EditText cid=in("Mutual connection ID"),c=in("Communication comfort"),f=in("Family progress"),d=in("Unresolved differences"),t=in("Timeline aligned?");Button s=bt("Save Private Check",true),b=bt("Back",false);s.setOnClickListener(x->{Map<String,Object> m=new HashMap<>();m.put("connectionId",cid.getText().toString());m.put("communication",c.getText().toString());m.put("familyProgress",f.getText().toString());m.put("unresolvedDifferences",d.getText().toString());m.put("timelineAligned",t.getText().toString());fn.getHttpsCallable("saveHealthCheck").call(m).addOnSuccessListener(y->toast("Private health check saved."));});b.setOnClickListener(x->home());}
 void verification(){base();title("Real Verification");EditText n=in("Verification note — never enter full ID numbers");Button s=bt("Submit Request",true),b=bt("Back",false);s.setOnClickListener(x->{Map<String,Object> m=new HashMap<>();m.put("userUid",auth.getUid());m.put("note",n.getText().toString());m.put("status","pending");m.put("createdAt",FieldValue.serverTimestamp());db.collection("verifications").add(m).addOnSuccessListener(y->toast("Verification request submitted."));});b.setOnClickListener(x->home());}
 void privacy(){base();title("Privacy Control Center");CheckBox d=new CheckBox(this),c=new CheckBox(this);d.setText("Show my profile in matching");c.setText("Show my city");root.addView(d);root.addView(c);Button s=bt("Save Privacy",true),b=bt("Back",false);db.collection("users").document(auth.getUid()).get().addOnSuccessListener(x->{d.setChecked(Boolean.TRUE.equals(x.getBoolean("discoverable")));c.setChecked(!Boolean.FALSE.equals(x.getBoolean("showCity")));});s.setOnClickListener(x->{Map<String,Object> m=new HashMap<>();m.put("discoverable",d.isChecked());m.put("showCity",c.isChecked());db.collection("users").document(auth.getUid()).set(m,SetOptions.merge()).addOnSuccessListener(y->toast("Privacy controls saved."));});b.setOnClickListener(x->home());}
 void safety(){base();title("Scam Shield");root.addView(tx("Never send money, OTPs, passwords or crypto. Never share identity documents in chat. Verification is not a guarantee. Report pressure, threats, impersonation and financial requests. Involve family/Wali for serious discussions.",16,false));Button b=bt("Back",false);b.setOnClickListener(x->home());}
 void reportBlock(String uid){new AlertDialog.Builder(this).setTitle("Safety action").setItems(new String[]{"Report","Block","Cancel"},(d,w)->{if(w==0)report(uid);if(w==1)block(uid);}).show();} void report(String uid){EditText e=new EditText(this);e.setHint("Reason");new AlertDialog.Builder(this).setTitle("Report user").setView(e).setPositiveButton("Send",(d,w)->{Map<String,Object> m=new HashMap<>();m.put("reporterUid",auth.getUid());m.put("reportedUid",uid);m.put("reason",e.getText().toString());m.put("status","pending");m.put("createdAt",FieldValue.serverTimestamp());db.collection("reports").add(m).addOnSuccessListener(x->toast("Report sent to moderation."));}).setNegativeButton("Cancel",null).show();} void block(String uid){Map<String,Object> m=new HashMap<>();m.put("blockedUid",uid);fn.getHttpsCallable("blockUser").call(m).addOnSuccessListener(x->{toast("User blocked.");home();});}
 void aiScreen(){base();title("AI Nikah Assistant");root.addView(tx("Real Firebase AI Logic. Supportive guidance only; no fatwas and no marriage guarantees.",15,false));EditText q=in("Ask a Nikah question");Button a=bt("Ask AI",true),b=bt("Back",false);TextView out=tx("",15,false);root.addView(out);a.setOnClickListener(x->runAI(q.getText().toString(),out));b.setOnClickListener(x->home());} void runAI(String prompt,TextView out){if(prompt.trim().length()<4){toast("Ask a clear question.");return;}out.setText("AI is preparing…");ai.execute(()->{try{GenerativeModel g=FirebaseAI.getInstance(GenerativeBackend.googleAI()).generativeModel("gemini-3.7-flash");GenerativeModelFutures m=GenerativeModelFutures.from(g);Content c=new Content.Builder().addText("You are Best Nikah Bridge AI. Be respectful, safety-first and concise. Never issue fatwas or claim marriage success. User: "+prompt).build();GenerateContentResponse r=m.generateContent(c).get();runOnUiThread(()->out.setText(r.getText()));}catch(Exception e){runOnUiThread(()->out.setText("AI temporarily unavailable. Verify important claims independently and consult a qualified scholar for religious rulings."));}});}
}
